package codegen

import (
	"bufio"
	"errors"
	"fmt"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"

	"github.com/kud360/goxsd8/xsd"
)

// fileName is the one file Generate writes into each Target's Dir.
const fileName = "xsd_gen.go"

// generatedHeader is the first line of every file Generate writes, in the
// form generatedLine recognizes.
const generatedHeader = "// Code generated by github.com/kud360/goxsd8/codegen. DO NOT EDIT."

// generatedLine is the Go convention's marker for a generated file. Generate
// overwrites an existing destination file only when its first line matches.
var generatedLine = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

// Target pairs one finalized schema with the package Generate emits for it. A
// field that breaks its rule below is a plain error before any write.
type Target struct {
	// Schema is the finalized schema to generate from; it must be non-nil.
	Schema *xsd.Schema
	// Dir is the output directory, non-empty, resolved relative to the
	// process working directory when it is not absolute.
	Dir string
	// Package is the emitted package's name: a Go identifier that is neither a
	// keyword, the blank identifier, nor main.
	Package string
	// Name names the target in Generate's errors; it may be empty.
	Name string
}

// name is the target's name, as Generate's doc defines it, for the target at
// slice index i.
func (t Target) name(i int) string {
	if t.Name != "" {
		return t.Name
	}
	return fmt.Sprintf("target %d", i)
}

// failed is err as Generate returns it for the target at slice index i,
// opened as Generate's doc states.
func (t Target) failed(i int, err error) error {
	if t.Name != "" {
		return fmt.Errorf("%s: %w", t.name(i), err)
	}
	return fmt.Errorf("codegen: %s: %w", t.name(i), err)
}

// Generate emits, for each target, one Go package of type declarations: the
// file xsd_gen.go in the target's Dir, declaring, in document order, one type
// per top-level element declaration of the target's Schema, one per
// anonymous complex type nested in its type definition, one per named
// complex type a local element declaration reaches, and one branch struct
// per alternative of each choice emitted as a sealed interface, each emitted
// after its parent, a field of an <element ref> particle holding the type
// emitted for the top-level element declaration it names, then one struct
// per date, time or duration datatype a declaration's type is declared over
// (the package doc's "Coverage" and "Naming" say which). A target's Schema is
// its whole composed set, so its {element declarations} (§3.17.1), and with
// them its file's top-level types, include those of every imported or
// included document, the overriding declaration standing in for each one an
// <xs:override> replaces, and a Schema with none gives a file that declares
// no type. Targets are generated independently: no emitted package imports
// another, so two targets whose Schemas share a document each declare types
// for its top-level element declarations, not necessarily under the same
// names.
//
// The file is gofmt-formatted. Generate writes no go.mod and adds no
// //go:generate line: the module the caller puts Dir in owns both.
//
// Generate runs in two phases. Phase 1 builds every target's source in
// memory, in slice order, and checks every destination; phase 2 writes. A
// target that fails phase 1 — an invalid Target, a Dir that equals an earlier
// target's after filepath.Clean, a Dir that filepath.Abs cannot make
// absolute, a construct the generator declines, or a failed destination check
// — means no target is written, and the error is the first failure in target
// order and then the order the generator meets declines: each top-level
// element declaration in document order, depth first through the types its
// particles reach (the package doc's "Coverage"). A local element that
// occurs exactly once and whose type, not a choice, is already emitted has
// that type checked again, through such elements, for a type reaching
// itself, and the decline "Coverage" states for one found there precedes
// every decline the depth-first walk meets after that element. The walk does
// not enter the type of the top-level declaration an <element ref> particle
// names, which that declaration's own turn emits; a ref to a declaration not
// yet reached checks that declaration's properties and the shape of its type
// where the ref is met, and a ref that occurs exactly once to a complex type
// that is not a choice has that type checked there, in the same way, for an
// element or type reaching itself, ahead of every decline the depth-first
// walk meets after the ref.
//
// Every error Generate returns opens with the failing target's name: its Name,
// or "target N" for the target at slice index N when Name is empty. An unnamed
// target's error opens "codegen: target N: ", a named one's "<Name>: " with no
// "codegen: " before it. The refusal of a Dir equal to an earlier target's
// names that earlier target the same way.
//
// A decline is a generator limitation, not a schema fault: it is a
// *DeclineError, never an *xsderr.Error, and it wraps errors.ErrUnsupported,
// so errors.Is(err, errors.ErrUnsupported) reports every decline and
// errors.As retrieves the *DeclineError from the error Generate returns. Its
// Construct method returns the construct declined, and its Loc method the Loc
// of the nearest component that carries one. Its text names both; the opening
// with the target's name, stated above, precedes that text and is no part of
// it. The package doc's "Coverage" section states what the generator accepts.
//
// Phase 2 creates Dir and its parents when absent. An existing xsd_gen.go is
// overwritten only when its first line matches `^// Code generated .* DO NOT
// EDIT\.$`; otherwise phase 1 fails. Generate never deletes a file and never
// touches another file in Dir. An I/O failure during phase 2 is the only
// failure that can leave some targets written and others not.
func Generate(targets []Target) error {
	sources := make([][]byte, len(targets))
	for i, t := range targets {
		src, err := prepare(t, targets[:i])
		if err != nil {
			return t.failed(i, err)
		}
		sources[i] = src
	}
	for i, t := range targets {
		if err := os.MkdirAll(t.Dir, 0o755); err != nil {
			return t.failed(i, fmt.Errorf("creating %s: %w", t.Dir, err))
		}
		path := filepath.Join(t.Dir, fileName)
		if err := os.WriteFile(path, sources[i], 0o644); err != nil {
			return t.failed(i, fmt.Errorf("writing %s: %w", path, err))
		}
	}
	return nil
}

// prepare is phase 1 for one target: it validates t against the targets
// before it, builds its source and checks its destination.
func prepare(t Target, earlier []Target) ([]byte, error) {
	if t.Schema == nil {
		return nil, errors.New("the Schema field is nil")
	}
	if t.Dir == "" {
		return nil, errors.New("no output directory given")
	}
	if token.IsKeyword(t.Package) {
		return nil, fmt.Errorf("the package name %q is a Go keyword", t.Package)
	}
	if t.Package == "_" {
		return nil, errors.New(`the package name "_" is the blank identifier`)
	}
	if !token.IsIdentifier(t.Package) {
		return nil, fmt.Errorf("the package name %q is not a Go identifier", t.Package)
	}
	if t.Package == "main" {
		return nil, errors.New(`the package name is "main", but the emitted package declares no func main and would not build`)
	}
	for j, e := range earlier {
		if filepath.Clean(e.Dir) == filepath.Clean(t.Dir) {
			return nil, fmt.Errorf("the output directory %s is also the output directory of %s", t.Dir, e.name(j))
		}
	}
	base, err := filepath.Abs(t.Dir)
	if err != nil {
		return nil, fmt.Errorf("resolving the output directory %s: %w", t.Dir, err)
	}
	src, err := emit(t.Schema, t.Package, base)
	if err != nil {
		return nil, err
	}
	if err := checkDestination(t.Dir); err != nil {
		return nil, err
	}
	return src, nil
}

// checkDestination fails unless phase 2 may write xsd_gen.go into dir: dir is
// absent or a directory, and the file is absent or a regular file whose first
// line marks it generated.
func checkDestination(dir string) error {
	info, err := os.Stat(dir)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("checking %s: %w", dir, err)
	}
	if !info.IsDir() {
		return fmt.Errorf("the output directory %s exists and is not a directory", dir)
	}
	path := filepath.Join(dir, fileName)
	info, err = os.Lstat(path)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("checking %s: %w", path, err)
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("%s exists and is not a regular file", path)
	}
	generated, err := isGenerated(path)
	if err != nil {
		return err
	}
	if !generated {
		return fmt.Errorf("%s exists and its first line does not mark it generated, so it is never overwritten", path)
	}
	return nil
}

// isGenerated reports whether the first line of the file at path matches
// generatedLine. A first line longer than bufio.Scanner's default token limit
// reads as not generated.
func isGenerated(path string) (generated bool, err error) {
	f, err := os.Open(path)
	if err != nil {
		return false, fmt.Errorf("checking %s: %w", path, err)
	}
	defer func() {
		if cerr := f.Close(); cerr != nil && err == nil {
			err = fmt.Errorf("closing %s: %w", path, cerr)
		}
	}()
	s := bufio.NewScanner(f)
	if !s.Scan() {
		if serr := s.Err(); serr != nil && !errors.Is(serr, bufio.ErrTooLong) {
			return false, fmt.Errorf("reading %s: %w", path, serr)
		}
		return false, nil
	}
	return generatedLine.MatchString(s.Text()), nil
}
